import{EVENT_TYPES}from"./interaction-tracker.js";const DEFAULT_HALF_LIFE_DAYS=30,BASE_WEIGHT=Object.freeze({[EVENT_TYPES.VIEW]:1,[EVENT_TYPES.SEARCH]:1.5,[EVENT_TYPES.BOOKMARK]:4,[EVENT_TYPES.UNBOOKMARK]:-4,[EVENT_TYPES.TRIP_PLANNED]:3}),CONFIDENCE_SATURATION=12;export function chooseCostTier(t,e){const n=t/Math.max(1,e||1);return n>=7e3?"luxury":n>=2800?"mid":"budget"}function ratingWeight(t){return 2*(Number(t)-3)}function decayFactor(t,e){const n=t/864e5;return Math.pow(.5,n/e)}function addWeighted(t,e,n){(e||0===e)&&(t[e]=(t[e]||0)+n)}export class AdaptivePreferenceEngine{constructor(t={}){this.destinations=t.destinations||[],this.halfLifeDays=t.halfLifeDays||30,this.now=t.now||(()=>Date.now())}_destination(t){return this.destinations.find(e=>e.id===t)}buildProfile(t=[]){const e="function"==typeof this.now?this.now():this.now,n={},i={},s={};let a=0;for(const o of t){const t=decayFactor(Math.max(0,e-(o.timestamp||e)),this.halfLifeDays);let r;r=o.type===EVENT_TYPES.RATING?ratingWeight(o.rating):BASE_WEIGHT[o.type]??0;const d=r*t;a+=Math.abs(d);const h=o.destinationId?this._destination(o.destinationId):null;if(h&&Array.isArray(h.tags)&&h.tags.length){const t=d/h.tags.length;h.tags.forEach(e=>addWeighted(n,e,t))}if(h&&h.budget&&addWeighted(i,h.budget,d),h&&Array.isArray(h.seasons)&&h.seasons.forEach(t=>addWeighted(s,t,d/h.seasons.length)),o.type===EVENT_TYPES.SEARCH&&o.query){const t=o.query.toLowerCase();new Set(this.destinations.flatMap(t=>t.tags||[])).forEach(e=>{t.includes(e)&&addWeighted(n,e,d)})}if(o.type===EVENT_TYPES.TRIP_PLANNED){if(o.budget&&o.days){addWeighted(i,chooseCostTier(o.budget,o.days),d)}o.month&&addWeighted(s,`month:${o.month}`,d)}}return{tagWeights:n,budgetWeights:i,seasonWeights:s,totalSignal:a,eventCount:t.length,confidence:Math.min(1,a/12)}}static isColdStart(t){return!t||t.confidence<.15}static getTopTags(t,e=3){return t?Object.entries(t.tagWeights).filter(([,t])=>t>0).sort((t,e)=>e[1]-t[1]).slice(0,e).map(([t])=>t):[]}static getPreferredBudget(t){if(!t)return null;const e=Object.entries(t.budgetWeights).filter(([,t])=>t>0);return e.length?e.sort((t,e)=>e[1]-t[1])[0][0]:null}}export default AdaptivePreferenceEngine;